REPLACE = {'frontend/src/App.jsx': {'before': '238c4cd81f90bb98f381399da22421a66dd2089a82d97df9192e0784dd8d36bc', 'after': 'import { Suspense, lazy, useCallback, useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport Overview from \'./Overview\';\nimport FamilyChips from \'./FamilyChips\';\nimport ConfidenceBadge from \'./ConfidenceBadge\';\nimport { attachStickyHeaders } from \'./stickyHeaders\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport RankingRevealCard from \'./cards/RankingRevealCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\n// loaded only when a tour starts, so driver.js is not in every page view\nconst Tour = lazy(() => import(\'./tour/Tour\'));\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  // Routes live in the URL hash, so Back and Forward work: #/overview (the\n  // default) or #/case/<id>. The last case opened stays loaded behind the\n  // overview, so returning to it is instant.\n  const parseRoute = () => {\n    const m = window.location.hash.match(/^#\\/case\\/([\\w-]+)/);\n    return m ? { view: \'case\', id: m[1] } : { view: \'overview\', id: null };\n  };\n  const [route, setRoute] = useState(parseRoute);\n  useEffect(() => {\n    const on = () => setRoute(parseRoute());\n    window.addEventListener(\'hashchange\', on);\n    return () => window.removeEventListener(\'hashchange\', on);\n  }, []);\n  const [lastCase, setLastCase] = useState(route.id ?? \'case_0001\');\n  if (route.id && route.id !== lastCase) setLastCase(route.id);\n  const incidentId = route.id ?? lastCase;\n  const openCase = useCallback((id) => { window.location.hash = `#/case/${id}`; }, []);\n  const openOverview = useCallback(() => { window.location.hash = \'#/overview\'; }, []);\n  // family filter for the overview grid; the sidebar always lists every case\n  const [family, setFamily] = useState(\'all\');\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n\n\n  const [touring, setTouring] = useState(false);\n\n  // Cross-fade between cases: the last fully loaded case stays on screen (dimmed)\n  // until the next has loaded, then fades in - rather than blanking and\n  // reloading. Updated during render, the standard pattern for derived state.\n  const [shown, setShown] = useState(null);\n  if (c && (shown?.c !== c || shown?.report !== report || shown?.tracks !== tracks)) {\n    setShown({ id: incidentId, c, report, tracks });\n  }\n  const vid = shown?.id;\n  const vc = shown?.c;\n  const leaving = !!shown && shown.id !== incidentId;\n  const meta = vc?.meta;\n\n  // scroll-edge effect on the pinned card headers; the column remounts per case\n  useEffect(() => attachStickyHeaders(document.querySelector(\'.finder-features\')), [vid, route.view]);\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && route.view === \'case\' && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          {route.view === \'case\' && vc && <ConfidenceBadge key={`conf-${vid}`} attribution={vc.attribution} />}\n          <button type="button" className={`tour-btn${touring ? \' is-on\' : \'\'}`} onClick={() => setTouring((t) => !t)}>\n            {touring ? \'Exit Tour\' : \'Start Tour\'}\n          </button>\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n      {touring && incidents.length > 0 && (\n        <Suspense fallback={null}>\n          <Tour incidents={incidents} api={api} selectCase={openCase} onExit={() => setTouring(false)} />\n        </Suspense>\n      )}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <button type="button" className={`nav-overview${route.view === \'overview\' ? \' is-active\' : \'\'}`} onClick={openOverview}>\n            <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 2h5v5H2zM9 2h5v5H9zM2 9h5v5H2zM9 9h5v5H9z" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" /></svg>\n            Overview\n          </button>\n          <CaseSwitcher incidents={incidents} active={route.view === \'case\' ? incidentId : null} onSelect={openCase} />\n        </aside>\n\n        {route.view === \'overview\' ? (\n          <Overview api={api} onOpen={openCase} family={family}\n                    chips={<FamilyChips incidents={incidents} value={family} onChange={setFamily} className="in-overview" />} />\n        ) : (\n        <div className={`finder-content${leaving ? \' is-leaving\' : \'\'}`} data-case={vid}>\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={vid}>\n            {vc && (\n              <>\n                <CaseFindingCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <RankingRevealCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <ObservedSceneCard meta={meta} slick={vc.slick} sceneUrl={api.sceneUrl(vid)}\n                                   nVessels={vc.vessels.length} />\n                <HistoricalReplayCard incidentId={vid} api={api} c={vc} tracks={shown.tracks} />\n                <FragilityCard fragility={vc.fragility} attribution={vc.attribution} />\n                <ForecastCard forecast={vc.forecast} />\n                <CoverageCard coverage={vc.coverage} />\n                <ProvenanceCard meta={meta} report={shown.report} />\n                {/* the case closes on what to check next */}\n                <NextObservationCard nextObs={vc.next_observation} closing />\n              </>\n            )}\n          </div>\n\n          <div className="finder-details" key={`d-${vid}`}>\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(vid)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(vid)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            {vc && (\n              <ConclusionGraph key={vid} attribution={vc.attribution} naive={vc.baseline}\n                               report={shown.report} detection={vc.slick} fragility={vc.fragility} />\n            )}\n            {vid && <AskSlickTraceCard key={`ask-${vid}`} incidentId={vid} api={api} />}\n          </div>\n        </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'}, 'frontend/src/cards/FragilityCard.jsx': {'before': 'a903a4dc645d049ee1fd4754487f733fc8a2fc5bda44e6919df09fa026f0e70d', 'after': 'import { useMemo, useState } from \'react\';\nimport { Badge, Card, EmptyState, Stat, StatGrid } from \'../ui/primitives\';\nimport \'./whatIf.css\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Rank fragility: what would have to change for the leader to change.\n *\n * Every value is a precomputed run on the server\'s grid. Choosing a setting\n * selects a computed point; nothing is interpolated for a setting that was\n * not run. On an abstained case the leader was never named, and says so.\n */\nconst AXIS_ORDER = [\'current_u_bias\', \'current_v_bias\', \'diffusivity_scale\', \'mask_threshold\', \'duration_shift_h\'];\n\nexport default function FragilityCard({ fragility, attribution }) {\n  const [axis, setAxis] = useState(\'current_u_bias\');\n  const [whatIf, setWhatIf] = useState(false);\n  const [pointId, setPointId] = useState(null);\n\n  const points = useMemo(() => (fragility?.grid ?? [])\n    .filter((g) => Object.keys(g.changed_axes).length === 1 && axis in g.changed_axes)\n    .sort((a, b) => a.changed_axes[axis] - b.changed_axes[axis]), [fragility, axis]);\n\n  if (!fragility) return null;\n  if (!fragility.testable) {\n    return (\n      <Card title="Rank Fragility" badge={<Badge tone="warning">not testable</Badge>}>\n        <EmptyState>Not testable for this incident: {fragility.reason}</EmptyState>\n      </Card>\n    );\n  }\n  const unnamed = fragility.baseline_unknown_source;\n  const flip = fragility.smallest_flip;\n  const selected = pointId ? fragility.grid.find((g) => g.point_id === pointId) : null;\n  const label = (k) => fragility.axes[k]?.label ?? k;\n\n  return (\n    <Card title="Rank Fragility"\n          badge={<Badge tone={fragility.flip_found ? \'warning\' : \'accent\'}>\n            {fragility.flip_found ? \'lead can flip\' : \'lead held\'}</Badge>}\n          caption="What would have to change in the assumptions for a different vessel to lead."\n          footnote={`${fragility.interpretation_note} ${fragility.coverage_note}`}>\n      <StatGrid cols={2}>\n        <Stat label={unnamed ? \'Unnamed leader (no source was named)\' : \'Leader\'} mono\n              value={fragility.baseline_top} caption="The vessel with the best fit before any change." />\n        <Stat label="Lead held"\n              value={`${Math.round(fragility.lead_retained_fraction * 100)}% of ${fragility.n_points_tested}`}\n              caption={C.leadHeld} />\n      </StatGrid>\n\n      {flip ? (\n        <div className="flip-box">\n          <StatGrid cols={2}>\n            <Stat label="Smallest change that flips the lead"\n                  value={Object.entries(flip.changed_axes).map(([k, v]) => `${label(k)} ${v}`).join(\', \')}\n                  caption={`Magnitude ${flip.magnitude}. ${C.magnitude}`} />\n            <Stat label="Leader under that change" mono value={flip.top_candidate}\n                  caption={`IoU ${flip.top_iou.toFixed(3)}; ${fragility.baseline_top} is now at IoU ${flip.baseline_candidate_iou.toFixed(3)}. `\n                    + (flip.top_iou < flip.baseline_candidate_iou ? C.lossRanking : C.meanIou)} />\n          </StatGrid>\n          <WhatIf fragility={fragility} attribution={attribution} flip={flip} on={whatIf} setOn={setWhatIf} label={label} />\n        </div>\n      ) : (\n        <p className="card-caption" style={{ marginTop: \'var(--space-4)\' }}>\n          No tested perturbation changed the leader.\n        </p>\n      )}\n\n      <div style={{ marginTop: \'var(--space-5)\' }}>\n        <div className="ui-row">\n          <label className="stat-label" htmlFor="frag-axis">Try one setting</label>\n          <select id="frag-axis" className="ui-select" value={axis}\n                  onChange={(e) => { setAxis(e.target.value); setPointId(null); }}>\n            {AXIS_ORDER.filter((a) => fragility.axes[a]).map((a) => (\n              <option key={a} value={a}>{label(a)}</option>\n            ))}\n          </select>\n        </div>\n        <p className="stat-caption">{C.sweep} Outlined values change the leader.</p>\n        <div className="chip-steps" role="group" aria-label={`Tested values for ${label(axis)}`}\n             style={{ marginTop: \'var(--space-2)\' }}>\n          {points.map((p) => (\n            <button key={p.point_id} type="button"\n                    className={`chip${pointId === p.point_id ? \' is-active\' : \'\'}${p.flipped ? \' is-flag\' : \'\'}`}\n                    aria-pressed={pointId === p.point_id}\n                    onClick={() => setPointId(pointId === p.point_id ? null : p.point_id)}>\n              {String(p.changed_axes[axis])}\n              <span className="visually-hidden">{p.flipped ? \' changes the leader\' : \' leader unchanged\'}</span>\n            </button>\n          ))}\n        </div>\n        {selected && (\n          <div style={{ marginTop: \'var(--space-4)\' }}>\n            <StatGrid cols={3}>\n              <Stat label="Leader under this setting" mono value={selected.top_candidate}\n                    caption={selected.flipped ? \'A different vessel leads.\' : \'Same leader as before.\'} />\n              <Stat label="Leader IoU" value={selected.top_iou.toFixed(3)} caption={C.meanIou} />\n              <Stat label="Margin over next vessel" value={selected.loss_margin ?? \'—\'} caption={C.lossMargin} />\n            </StatGrid>\n          </div>\n        )}\n      </div>\n    </Card>\n  );\n}\n\n/**\n * "What if conditions were slightly different?" - the tested ranking against the\n * smallest tested change that flips the lead, for the two vessels that swap.\n * Ranking is by loss (lower is better); IoU is shown alongside. Each tested change\n * stores only its leader and the tested leader\'s fit, so only those two rows are\n * shown under it - the rest of that ranking was not stored.\n */\nfunction WhatIf({ fragility, attribution, flip, on, setOn, label }) {\n  const a = fragility.baseline_top, b = flip.top_candidate;\n  const rank = (k) => (attribution?.ranking ?? []).findIndex((r) => r.vessel_key === k) + 1;\n  const iou0 = (k) => (attribution?.ranking ?? []).find((r) => r.vessel_key === k)?.mean_iou;\n  const loss0 = fragility.nominal_mean_losses ?? {};\n  const change = Object.entries(flip.changed_axes).map(([k, v]) => `${label(k)} ${v}`).join(\', \');\n  const rows = [\n    { key: a, pos: on ? 1 : 0, iou: on ? flip.baseline_candidate_iou : iou0(a),\n      note: on ? \'now behind\' : `#${rank(a)} as tested · loss ${loss0[a]?.toFixed(3) ?? \'—\'}`, lead: !on },\n    { key: b, pos: on ? 0 : 1, iou: on ? flip.top_iou : iou0(b),\n      note: on ? `leads by a loss margin of ${flip.loss_margin}` : `#${rank(b)} as tested · loss ${loss0[b]?.toFixed(3) ?? \'—\'}`, lead: on },\n  ];\n  return (\n    <div className="whatif">\n      <div className="whatif-head">\n        <span className="whatif-q">What if conditions were slightly different?</span>\n        <div className="whatif-seg" role="group" aria-label="Show the ranking as tested or with the smallest flipping change">\n          <button type="button" className={!on ? \'is-on\' : \'\'} aria-pressed={!on} onClick={() => setOn(false)}>As tested</button>\n          <button type="button" className={on ? \'is-on\' : \'\'} aria-pressed={on} onClick={() => setOn(true)}>With {change}</button>\n        </div>\n      </div>\n      <div className="whatif-rows" role="table" aria-label="The two vessels that swap">\n        {rows.map((r) => (\n          <div key={r.key} role="row" className={`whatif-row${r.lead ? \' is-lead\' : \'\'}`}\n               style={{ transform: `translateY(${r.pos * 46}px)`, \'--w\': Math.max(0, Math.min(1, r.iou ?? 0)) }}>\n            <span className="whatif-pos" role="cell">{r.pos + 1}</span>\n            <span className="whatif-key" role="cell">{r.key}</span>\n            <span className="whatif-track" role="cell" aria-hidden="true"><span className="whatif-fill" /></span>\n            <span className="whatif-iou" role="cell">{r.iou != null ? r.iou.toFixed(3) : \'—\'}</span>\n            <span className="whatif-note" role="cell">{r.note}</span>\n          </div>\n        ))}\n      </div>\n      <p className="whatif-foot">\n        {on ? `With ${change} (magnitude ${flip.magnitude}), ${b} leads instead of ${a}. `\n          : `As tested, ${a} leads. `}\n        Ranked by loss; the bar is mean IoU. Only these two vessels\' fits are stored for each tested change, so the\n        rest of the ranking under it is not shown.\n      </p>\n    </div>\n  );\n}\n'}}
NEW = {'frontend/src/cards/whatIf.css': '.whatif { margin-top: var(--space-4); padding: 12px 14px; border-radius: 10px; background: var(--surface-raised);\n          box-shadow: inset 0 0 0 0.5px var(--separator); }\n.whatif-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }\n.whatif-q { font-weight: var(--font-weight-semibold); font-size: var(--font-size-sm); color: var(--label-1); }\n.whatif-seg { display: inline-flex; padding: 2px; border-radius: 8px; background: var(--fill-pressed); }\n.whatif-seg button { height: 26px; padding: 0 12px; border: 0; border-radius: 6px; cursor: default; font: inherit;\n                     font-size: var(--font-size-xs); font-weight: var(--font-weight-medium); color: var(--label-1); background: transparent;\n                     transition: background-color var(--dur-fast) ease, box-shadow var(--dur-fast) ease; }\n.whatif-seg button.is-on { background: var(--control-bg); box-shadow: var(--shadow-control); }\n.whatif-seg button:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 1px; }\n.whatif-rows { position: relative; height: 92px; }\n.whatif-row { position: absolute; left: 0; right: 0; top: 0; height: 40px; display: grid; align-items: center; gap: 12px; padding: 0 10px;\n              grid-template-columns: 18px minmax(92px, 112px) minmax(80px, 1fr) 52px minmax(150px, 1.2fr); border-radius: 9px;\n              transition: transform 620ms cubic-bezier(0.34, 1.26, 0.64, 1), background-color 300ms ease, box-shadow 300ms ease; }\n.whatif-pos { font-family: var(--font-mono); font-size: var(--font-size-xs); color: var(--label-3); text-align: right; }\n.whatif-key { font-family: var(--font-mono); font-size: var(--font-size-sm); }\n.whatif-track { position: relative; height: 8px; border-radius: 4px; background: var(--fill-pressed); }\n.whatif-fill { position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--w) * 100%); border-radius: 4px; background: var(--label-3);\n               transition: width 620ms cubic-bezier(0.34, 1.1, 0.64, 1), background-color 300ms ease; }\n.whatif-iou { font-family: var(--font-mono); font-size: var(--font-size-sm); text-align: right; font-variant-numeric: tabular-nums; }\n.whatif-note { font-size: var(--font-size-xs); color: var(--label-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.whatif-row.is-lead { background: rgba(10, 132, 255, 0.12); box-shadow: inset 0 0 0 0.5px rgba(10, 132, 255, 0.55); }\n.whatif-row.is-lead .whatif-fill { background: linear-gradient(90deg, #0a84ff, #5ac8fa); }\n.whatif-row.is-lead .whatif-key, .whatif-row.is-lead .whatif-iou { font-weight: var(--font-weight-semibold); }\n.whatif-foot { margin: 10px 0 0; font-size: var(--font-size-xs); color: var(--label-2); }\n@media (prefers-reduced-motion: reduce) { .whatif-row, .whatif-fill { transition: none; } }\n'}
CL_OLD = 'It links to the provenance card. The synthetic-case tag stays separate.\n'
CL_NEW = 'It links to the provenance card. The synthetic-case tag stays separate.\n\n**Fragility: "What if conditions were slightly different?"** Where a tested change flips the\nlead, the fragility card toggles between the ranking as tested and with the smallest such\nchange, animating the two vessels that swap, with their fits, tested ranks and loss, and\nthe margin. Every value is from fragility_result.json and attribution_result.json. Each\ntested change stores only its leader and the tested leader\'s fit, so the rest of the\nranking under it is not shown, and the card says so.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 32 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 33: {len(writes)} files written, {skipped} already in place.")
